  // Emitter silhouettes.
  const emitterStyle = emitter.style;
  round(-hiltWidth * .42, .98, hiltWidth * .84, .12, .02, bodyDark);
  let emitterTop = 1.20;
  if (emitterStyle === 'flare') {
    poly([[-.16, 1.02], [.16, 1.02], [.23, 1.22], [-.23, 1.22]], body);
