  record.losses += 1;
  record.streak = 0;
  saveDuelRecord();
  playTone(150, .2);
  announceDuel('THE RING WINS THIS ROUND', 'is-hit');
  addDuelLog(`You are disarmed. The lesson is yours.`, 'is-bad');
  updateDuelProfileUI();
