  const rest = facing === 1 ? -1.02 : -2.12;
  const anim = duel.anim[side];
  const raw = anim.kind ? (now - anim.start) / anim.dur : 1;
  const p = Math.max(0, Math.min(1, raw));
  const kind = anim.kind && raw < 1 ? anim.kind : '';
