  if (kind === 'attack' || kind === 'heavy') {
    const windup = rest - facing * (kind === 'heavy' ? .68 : .44);
    const target = facing === 1 ? (kind === 'heavy' ? .46 : .18) : (kind === 'heavy' ? -3.14 : -2.96);
