  const foe = buildDuelOpponent();
  duel.player.name = duel.selectedArtifact.name;
  rollDuelIntent();
  updateDuelBattleUI(true);
  renderDuelLog();
  announceDuel('ROUND 01 · ENGAGE', '');
  addDuelLog(`You enter the ring against ${foe.name}.`);
  playTone(560, .1);
  requestAnimationFrame(() => {
