const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright');
const parts = { hilt: 1, emitter: 2, grip: 3, pommel: 1, crystal: 2, accent: 1, blade: 0, switch: 1, engraving: 2 };
const collection = [
  { id: 'a1', name: 'Silent Resolve', parts, blade: true, value: 2400, createdAt: new Date().toISOString() },
  { id: 'a2', name: 'Wandering Dawn', parts: { ...parts, hilt: 2, crystal: 5 }, blade: true, value: 2800, createdAt: new Date().toISOString() },
  { id: 'a3', name: 'Last Horizon', parts: { ...parts, hilt: 4, crystal: 7 }, blade: true, value: 3200, createdAt: new Date().toISOString() }
];

(async () => {
  const browser = await chromium.launch();
  const sizes = [[1440, 900], [1280, 800], [1024, 768], [820, 900], [768, 900], [480, 800], [390, 844]];
  for (const [w, h] of sizes) {
    const context = await browser.newContext({ viewport: { width: w, height: h } });
    await context.addInitScript(c => localStorage.setItem('sabersmith.collection.v1', JSON.stringify(c)), collection);
    const page = await context.newPage();
    const errs = [];
    page.on('pageerror', e => errs.push(e.message));
    await page.goto('http://localhost:8123/index.html');
    await page.waitForTimeout(2200);
    await page.click('#activitiesButton');
    await page.click('#activityDuel');
    await page.waitForTimeout(500);
    const lobby = await page.evaluate(() => {
      const room = document.querySelector('#duelLobby');
      const grid = document.querySelector('.duel-lobby-grid');
      const foot = document.querySelector('#duelLobby .activity-stage-footer');
      return {
        roomW: room.clientWidth, roomScrollW: room.scrollWidth,
        gridW: grid.clientWidth, gridScrollW: grid.scrollWidth,
        footerBottom: Math.round(foot.getBoundingClientRect().bottom),
        viewportH: innerHeight,
        startVisible: !!document.querySelector('#duelStart').getClientRects().length
      };
    });
    const startBox = await page.locator('#duelStart').boundingBox();
    await page.click('#duelStart');
    await page.waitForTimeout(850);
    const arena = await page.evaluate(() => {
      const stage = document.querySelector('.duel-stage');
      const hudE = document.querySelector('.duel-hud-enemy').getBoundingClientRect();
      const hudP = document.querySelector('.duel-hud-player').getBoundingClientRect();
      const acts = document.querySelector('.duel-actions').getBoundingClientRect();
      return {
        stageW: stage.clientWidth,
        hudP: [Math.round(hudP.x), Math.round(hudP.right)],
        hudE: [Math.round(hudE.x), Math.round(hudE.right)],
        acts: [Math.round(acts.x), Math.round(acts.right)],
        docScrollW: document.documentElement.scrollWidth
      };
    });
    console.log(`${w}x${h}`, JSON.stringify({ lobby, startBox: startBox && { y: Math.round(startBox.y), bottom: Math.round(startBox.y + startBox.height) }, arena, errs }));
    if (w === 1440 || w === 390) {
      await page.screenshot({ path: `/tmp/opencode/shots/final-${w}.png` });
    }
    await context.close();
  }
  await browser.close();
})();

